@js:
function parseChapterContent(rawContent) {
    let result = String(rawContent || '');

    try {
        let json = JSON.parse(result);
        if (json.picInfos && Array.isArray(json.picInfos)) {
            return json.picInfos
                .map(pic => {
                    let url = `https://p3-novel.byteimg.com/origin/novel-pic/${pic.md5}`;
                    return `<img src="${url}">`;
                })
                .join('\n');
        }
        if (json.content) {
            return parseChapterContent(json.content);
        }
        result = JSON.stringify(json);
    } catch (e) {}

    let articleMatch = result.match(/<article>([\s\S]*?)<\/article>/i);
    if (articleMatch) {
        let inner = articleMatch[1]
            .replace(/&/g, '"')
            .replace(/;/g, '')
            .replace(/#34/g, '');
        try {
            let cnt = JSON.parse(inner);
            if (cnt.skeleton && cnt.skeleton.data && cnt.materials) {
                return cnt.skeleton.data
                    .map(item => {
                        let webUri = cnt.materials[item.element_name].data.web_uri;
                        return `<img src="https://p3-novel.byteimg.com/origin/${webUri}">`;
                    })
                    .join('\n');
            }
        } catch (e) {}
        result = articleMatch[1];
    } else {
        let bodyMatch = result.match(/<body>([\s\S]*?)<\/body>/i);
        if (bodyMatch) result = bodyMatch[1];
    }

    result = result
        .replace(/<tt_keyword_ad[^>]*>[\s\S]*?<\/tt_keyword_ad>/gi, '')
        .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
        .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
        .replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, '$1')
        .replace(/<a[^>]*\/>/gi, '')
        .replace(/<!DOCTYPE[^>]*>/gi, '')
        .replace(/<\/?html[^>]*>/gi, '')
        .replace(/<head>[\s\S]*?<\/head>/gi, '');

    result = result
        .replace(/<p[^>]*>/gi, '\n')
        .replace(/<\/p>/gi, '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/?blk[^>]*>/gi, '');

    result = result.replace(/<[^>]+>/g, '');

    result = result
        .replace(/&nbsp;/g, ' ')
        .replace(/\r\n/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

    result = result.replace(
        /\[插图\s*[:：]\s*(https?:\/\/[^\s\[\]]+?)\s*\]/gi,
        '<img src="$1">'
    );

    result = result
        .replace(/&#34;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&quot;/g, '"')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>');

    result = result.replace(/\{\!\-\- PGC_VOICE\:.*\-\-\}/g, '');

    return result;
}

